/* Shared admin session, CSRF, navigation and modal helpers. */
const cp='admin/ims/compliance/';
const nice=s=>String(s||'').replaceAll('_',' ');
const privileged=()=>['admin','manager'].includes(me.role);
function goButtons(v){v.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>load(b.dataset.go));}
async function imsDashboard(v){
 const x=await api('admin/overview');let d=null,c=null,errors=[];
 if(privileged()){const r=await Promise.allSettled([api('admin/ims/summary'),api(cp+'summary')]);d=r[0].status==='fulfilled'?r[0].value:null;c=r[1].status==='fulfilled'?r[1].value:null;errors=r.filter(y=>y.status==='rejected').map(y=>y.reason.message);}
 if(tab!=='overview')return;
 const count=(a,states)=>a? a.filter(y=>states.includes(y.status)).reduce((n,y)=>n+Number(y.n),0):'—';
 const active=count(x.work_orders,['open','assigned','accepted','in_progress','blocked']);const total=x.work_orders.reduce((n,y)=>n+Number(y.n),0);
 const metrics=[['Active assignments',active,'work-orders'],['Partner review',count(x.partners,['applied','screening','verified']),'partners'],['Approved partners',count(x.partners,['approved']),'partners'],['New enquiries',x.new_enquiries,'enquiries'],...(privileged()?[['Documents in review',count(d?.documents,['review']),'documents'],['Open governance actions',count(c?.records,['open','in_progress']),'governance']]:[])];
 v.innerHTML=`<section class="command-head"><div><div class="ims-kicker">Service delivery / governance</div><h2>Operations command centre</h2><p>Monitor assignments, decisions and supporting records.</p></div><div class="ims-actions"><button class="btn small" data-go="work-orders">Work orders →</button>${privileged()?'<button class="btn small" data-go="compliance">Review controls →</button>':''}</div></section><div class="command-metrics">${metrics.map(([t,n,k])=>`<button class="ims-metric" data-go="${k}"><small>${esc(t)}</small><strong>${esc(n)}</strong><small>Open workspace →</small></button>`).join('')}</div><div class="command-grid"><section class="ims-panel"><h3>Delivery pipeline</h3><p class="ims-muted">${total} recorded assignments</p>${['open','assigned','accepted','in_progress','blocked','completed','cancelled'].map(s=>{const n=count(x.work_orders,[s]);return `<div class="pipe-row"><span>${nice(s)}</span><progress class="pipe-track" max="${Math.max(total,1)}" value="${n}" aria-label="${nice(s)} assignments"></progress><b>${n}</b></div>`}).join('')}</section><section class="ims-panel"><h3>Control assessments</h3><p class="ims-muted">Internal assessments, not certification status.</p>${privileged()?['unassessed','planned','implemented','verified','not_applicable'].map(s=>`<div class="ims-line"><span>${nice(s)}</span><strong>${count(c?.controls,[s])}</strong></div>`).join(''):'<p>Restricted workspace</p>'}${privileged()?'<button class="btn small" data-go="compliance">Open requirements register</button>':''}</section><section class="ims-panel"><h3>Priority actions</h3>${!c?'<p>Governance records unavailable or restricted.</p>':c.urgent.length?c.urgent.map(y=>`<div class="action-item"><span class="priority ${esc(y.priority)}">${esc(y.priority)}</span><div><strong>${esc(y.title)}</strong><small>${esc(nice(y.kind))} · ${date(y.due_date)}</small></div></div>`).join(''):'<p class="ims-muted">No high-priority or overdue open actions recorded.</p>'}${privileged()?'<button class="btn small" data-go="governance">View actions</button>':''}</section><section class="ims-panel"><h3>Recent activity</h3><div class="command-timeline">${x.activity.slice(0,6).map(y=>`<div><strong>${esc(nice(y.entity_type))} #${esc(y.entity_id)}</strong><span>${esc(nice(y.action))}</span><small>${date(y.created_at)}</small></div>`).join('')||'<p>No activity recorded.</p>'}</div><button class="btn small" data-go="activity">Full activity log</button></section></div>${errors.length?`<div class="message error">${errors.map(esc).join(' · ')}</div>`:''}<p class="ims-muted">Evidence export: available in Audit & Assurance for administrators. Document repository: ${d?'available':privileged()?'unavailable':'restricted'}.</p>`;goButtons(v);
}
function options(a){return a.map(s=>`<option value="${esc(s)}">${esc(nice(s))}</option>`).join('');}
function choice(name,label,a){return `<div class="field"><label>${esc(label)}</label><select name="${name}">${options(a)}</select></div>`;}
function noteField(name,label){return `<div class="field"><label>${esc(label)}</label><textarea name="${name}" maxlength="5000" required></textarea></div>`;}
function evidenceChoice(docs){return `<div class="field"><label>Approved document evidence</label><select name="evidence_version_id"><option value="">None</option>${docs.filter(d=>d.status==='approved').map(d=>`<option value="${esc(d.id)}">${esc(d.code)} · revision ${esc(d.revision)} · ${esc(d.title)}</option>`).join('')}</select></div>`;}
function modalFlow(title,first,second,path,transform){showModal(title,`<form id="control-form"><div class="ims-progress"><span></span></div><div class="ims-step active">${first}<button type="button" class="btn" id="flow-next">Continue →</button></div><div class="ims-step">${second}<div class="ims-row"><button type="button" class="btn outline" id="flow-back">Back</button><button class="btn" type="submit">Record submission</button></div></div><div id="flow-error" role="alert"></div></form>`);const f=document.querySelector('#control-form'),steps=f.querySelectorAll('.ims-step');function step(n){steps.forEach((s,i)=>s.classList.toggle('active',i===n));f.querySelector('.ims-progress').classList.toggle('second',n===1);steps[n].scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});steps[n].querySelector('input,select,textarea,button')?.focus({preventScroll:true});}f.querySelector('#flow-next').onclick=()=>{for(const el of steps[0].querySelectorAll('input,select,textarea'))if(!el.reportValidity())return;step(1);};f.querySelector('#flow-back').onclick=()=>step(0);f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('[type=submit]');if(btn.disabled)return;btn.disabled=true;try{operationalState('Validating and recording submission…');await api(cp+path,'POST',transform(Object.fromEntries(new FormData(f))));closeModal();operationalState('Change recorded.',true);await load(tab);}catch(err){operationalState('Submission not confirmed.',true);f.querySelector('#flow-error').textContent=err.message;}finally{btn.disabled=false;}};}
async function complianceView(v){const [rows,opt,docs]=await Promise.all([api(cp+'controls'),api(cp+'options'),api('admin/ims/documents')]);if(tab!=='compliance')return;v.innerHTML=`<section class="ims-panel"><div class="ims-row"><div><h3>Requirements register</h3><p class="ims-muted">Enter verified source references and applicable obligations. No standards coverage is assumed.</p></div><button class="btn" id="new-control">Add requirement</button></div>${table(['Framework / reference','Requirement','Assessment','Evidence','Action'],rows.map(r=>`<tr><td>${esc(r.framework)}<br>${esc(r.reference)}</td><td><strong>${esc(r.title)}</strong><br>${esc(r.description)}</td><td>${esc(nice(r.status))}</td><td>${r.evidence_version_id?`Revision #${esc(r.evidence_version_id)} · ${esc(r.evidence_status)}${r.evidence_status!=='approved'?' · re-evaluate':''}`:'None'}</td><td><button class="btn small" data-assess="${esc(r.id)}">Assess</button></td></tr>`))}</section>`;v.querySelector('#new-control').onclick=()=>modalFlow('Register requirement',field('framework','Framework / source','text','',true)+`<p class="ims-muted">Examples: ${esc(opt.frameworks.join(', '))}</p>`+field('reference','Clause or customer reference','text','',true)+field('title','Requirement title','text','',true),noteField('description','Applicable requirement and intended control')+field('due_date','Review due','date'),'controls',x=>({...x,due_date:x.due_date||null}));v.querySelectorAll('[data-assess]').forEach(b=>b.onclick=()=>modalFlow('Record control assessment',choice('status','Assessment',['unassessed','planned','implemented','verified','not_applicable'])+noteField('note','Assessment justification'),evidenceChoice(docs)+ '<p class="ims-muted">Internal assessment only. Evidence must be reviewed for relevance and effectiveness.</p>',`controls/${b.dataset.assess}/assessment`,x=>({...x,evidence_version_id:x.evidence_version_id||null})));}
async function governanceView(v){const [rows,opt,controls,docs]=await Promise.all([api(cp+'records'),api(cp+'options'),api(cp+'controls'),api('admin/ims/documents')]);if(tab!=='governance')return;v.innerHTML=`<section class="ims-panel"><div class="ims-row"><div><h3>Governance and action register</h3><p class="ims-muted">Risks, incidents, environmental aspects, supplier reviews and more.</p></div><button class="btn" id="new-record">Register action</button></div><div class="field"><label>Filter record type</label><select id="kind-filter"><option value="">All record types</option>${options(opt.kinds)}</select></div><div id="gov-table"></div></section>`;const draw=()=>{const k=v.querySelector('#kind-filter').value;v.querySelector('#gov-table').innerHTML=table(['Record','Priority','Status','Due','Action'],rows.filter(r=>!k||r.kind===k).map(r=>`<tr><td><strong>${esc(r.title)}</strong><br>${esc(nice(r.kind))}<br>${esc(r.description)}</td><td><span class="priority ${esc(r.priority)}">${esc(r.priority)}</span></td><td>${esc(nice(r.status))}</td><td>${date(r.due_date)}</td><td><button class="btn small" data-record="${esc(r.id)}">Update</button></td></tr>`));v.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>modalFlow('Update governance record',choice('status','Status',['open','in_progress','closed'])+noteField('note','Action or closure justification'),evidenceChoice(docs),`records/${b.dataset.record}/action`,x=>({...x,evidence_version_id:x.evidence_version_id||null})));};v.querySelector('#kind-filter').onchange=draw;draw();v.querySelector('#new-record').onclick=()=>modalFlow('Register governance record',choice('kind','Record type',opt.kinds)+field('title','Title','text','',true)+noteField('description','Description and planned action'),choice('priority','Priority',['medium','low','high','critical'])+field('due_date','Action due','date')+`<div class="field"><label>Related requirement</label><select name="control_id"><option value="">None</option>${controls.map(r=>`<option value="${esc(r.id)}">${esc(r.framework)} · ${esc(r.reference)} · ${esc(r.title)}</option>`).join('')}</select></div>`,'records',x=>({...x,due_date:x.due_date||null,control_id:x.control_id||null}));}
